def apply_correction(planet, meeus_lon, maya_day):
    if planet not in CORRECTIONS: return meeus_lon
    corr = CORRECTIONS[planet]
    idx = maya_day - CORR_START
    if idx < 0 or idx >= len(corr): return meeus_lon
    return (meeus_lon + corr[idx]) % FULL_CIRCLE
